'use strict';
const assert = require('node:assert/strict');
const { createParser, parse } = require(process.argv[2]);

const eq = (t, exp, o) => assert.deepEqual(parse(t, o), exp, JSON.stringify(t));
eq('', []);
eq('\uFEFF', []);
eq('\n', [['']]);
eq('\n\n', [[''], ['']]);
eq('a\n', [['a']]);
eq('a\r\nb\rc\n', [['a'], ['b'], ['c']]);
eq('a,b"c"d', [['a', 'b"c"d']]);
eq('"x\r\ny\rz",', [['x\r\ny\rz', '']]);
eq('"",""""', [['', '"']]);
eq('a;b,c', [['a', 'b,c']], { delimiter: ';' });
eq('a\tb', [['a', 'b']], { delimiter: '\t' });
eq('\uFEFFa,\uFEFF', [['a', '\uFEFF']]);
eq('"a"\r\n', [['a']]);
eq('', [], { header: true });
eq('a,a\n1', [{ a: '1', a_2: '' }], { header: true });

const synLine = (t, n) => assert.throws(() => parse(t), e => e instanceof SyntaxError && e.message.includes(`line ${n}`), t);
synLine('"a" ,b', 1);
synLine('x\r\n"a\r\nb"c', 3);
synLine('x\r\r\n\n"a"x', 4);
synLine('"abc\n', 2);
synLine('"abc\r\n', 2);

for (const d of ['', ',,', '"', '\r', '\n', 5, null]) assert.throws(() => createParser({ delimiter: d }), RangeError);

let p = createParser();
assert.throws(() => p.push(1), TypeError);
assert.deepEqual(p.push('a\r'), [['a']]);
assert.deepEqual(p.push('\n'), []);
assert.deepEqual(p.push('b'), []);
assert.deepEqual(p.end(), [['b']]);
assert.deepEqual(p.end(), []);
assert.throws(() => p.push(''), Error);

p = createParser();
assert.deepEqual(p.push(''), []);
assert.deepEqual(p.push('\uFEFFa'), []);
assert.deepEqual(p.end(), [['a']]);

// CRLF split across chunks counts once for line numbers
p = createParser();
p.push('"a\r'); p.push('\nb"\r'); p.push('\n"c');
assert.throws(() => p.push('"z'), /line 3/);

// Every split of a set of tricky inputs gives the same result as one push.
const inputs = ['\uFEFFa,"b""c"\r\n"d\r\ne",\r\r\n\nx"y\r', '"",""""\n,\r\n"\uD83D\uDE00",\uD83D\uDE00', '"a"\r\n'];
for (const s of inputs) {
  const whole = parse(s);
  for (let i = 0; i <= s.length; i++) {
    for (let j = i; j <= s.length; j++) {
      const q = createParser();
      const out = [...q.push(s.slice(0, i)), ...q.push(''), ...q.push(s.slice(i, j)), ...q.push(s.slice(j)), ...q.end()];
      assert.deepEqual(out, whole, `${JSON.stringify(s)} @${i},${j}`);
    }
  }
}
// records are emitted eagerly
p = createParser();
assert.deepEqual(p.push('a\nb'), [['a']]);
console.log('ok');

