      const c = chunk[i];

      // Physical line counting covers quoted content too; CRLF counts once.
      if (c === '\r') line++;
      else if (c === '\n' && !prevCR) line++;
      prevCR = c === '\r';

      if (skipLF) {
        skipLF = false;
        if (c === '\n') continue;
      }

      switch (state) {
        case FIELD_START:
          if (c === '"') {
            state = QUOTED;
            rowStarted = true;
          } else if (c === delimiter) {
            row.push(field);
            rowStarted = true;
          } else if (c === '\r' || c === '\n') {
            endRecord();
            skipLF = c === '\r';
          } else {
            field += c;
            state = UNQUOTED;
            rowStarted = true;
          }
          break;
        case UNQUOTED:
          if (c === delimiter) {
            row.push(field);
            field = '';
            state = FIELD_START;
          } else if (c === '\r' || c === '\n') {
            endRecord();
            skipLF = c === '\r';
          } else {
            field += c;
          }
          break;
        case QUOTED:
          if (c === '"') state = AFTER_QUOTE;
          else field += c;
          break;
        case AFTER_QUOTE:
          if (c === '"') {
            field += '"';
            state = QUOTED;
          } else if (c === delimiter) {
            row.push(field);
            field = '';
            state = FIELD_START;
          } else if (c === '\r' || c === '\n') {
            endRecord();
            skipLF = c === '\r';
          } else {
            throw new SyntaxError(`Unexpected character after closing quote at line ${line}`);
          }
          break;
      }
    }
    return records;
  }

  function end() {
    if (ended) return [];
    ended = true;
    if (state === QUOTED) {
      throw new SyntaxError(`Unterminated quoted field at line ${line}`);
    }
    if (!rowStarted) return [];
    row.push(field);
    const last = row;
    row = [];
    field = '';
    rowStarted = false;
    return [last];
  }

  return { push, end };
}

function normalizeOptions(options) {
  if (options === undefined || options === null) return {};
  if (typeof options !== 'object') throw new TypeError('options must be an object');
  return options;
}

/**
 * Parse all text using the same grammar and validation as createParser.
 * With options.header === true, convert records with the existing
 * toObjects(records, { header: true }) helper; otherwise return string[][].
 * Empty input yields [] in either mode. Do not change the helper's contract.
 */
function parse(text, options) {
  const opts = normalizeOptions(options);
  const parser = createParser(opts);
  const records = parser.push(text).concat(parser.end());
  return opts.header === true ? toObjects(records, { header: true }) : records;
}

module.exports = { createParser, parse };

